import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import axios from 'axios';



const HomePage = () => {
  const [isFormVisible, setIsFormVisible] = useState(false);
  const [registrationNumber, setRegistrationNumber] = useState('');
  const [ownerPhone, setOwnerPhone] = useState('');
  const [model, setModel] = useState('');
  const [yearBuilt, setYearBuilt] = useState('');
  const [lorries, setLorries] = useState([]);

  useEffect(() => {
    fetchLorries();
  }, []);

  const fetchLorries = async () => {
    try {
      const response = await axios.get('/api/lorries');
      setLorries(response.data);
    } catch (error) {
      console.error('Error fetching lorries:', error);
    }
  };

  const handleAddLorry = () => {
    setIsFormVisible(!isFormVisible);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const newLorry = { registration_number: registrationNumber, owner_phone: ownerPhone, model, year_built: yearBuilt };
      await axios.post('/api/lorries', newLorry);
      alert('Lorry added successfully');
      setIsFormVisible(false);  // Hide form after submission
      fetchLorries();  // Fetch updated list of lorries
    } catch (error) {
      console.error('Error adding lorry:', error);
      alert('Failed to add lorry');
    }
  };

  const handleDeleteLorry = async (registrationNumber) => {
    try {
      await axios.delete(`/api/lorries/${registrationNumber}`);
      alert('Lorry deleted successfully');
      fetchLorries();  // Fetch updated list of lorries
    } catch (error) {
      console.error('Error deleting lorry:', error);
      alert('Failed to delete lorry');
    }
  };

  return (
    <Container>
      {/* Header with company info */}
      <Header>
        <CompanyName>Sri Murugan Rig Service</CompanyName>
        <OwnerInfo>
          <div>K Thangavelu</div>
          <div>9443769338</div>
        </OwnerInfo>
      </Header>

      {/* Add Lorry Button */}
      <AddLorryButton onClick={handleAddLorry}>
        {isFormVisible ? 'Cancel' : 'Add Lorry'}
      </AddLorryButton>

      {/* Add Lorry Form */}
      {isFormVisible && (
        <AddLorryForm onSubmit={handleSubmit}>
          <Input
            type="text"
            placeholder="Registration Number"
            value={registrationNumber}
            onChange={(e) => setRegistrationNumber(e.target.value)}
            required
          />
          <Input
            type="text"
            placeholder="Owner Phone"
            value={ownerPhone}
            onChange={(e) => setOwnerPhone(e.target.value)}
            required
          />
          <Input
            type="text"
            placeholder="Model"
            value={model}
            onChange={(e) => setModel(e.target.value)}
            required
          />
          <Input
            type="number"
            placeholder="Year Built"
            value={yearBuilt}
            onChange={(e) => setYearBuilt(e.target.value)}
            required
          />
          <button type="submit">Add Lorry</button>
        </AddLorryForm>
      )}

      {/* Display List of Lorries */}
      {lorries.length > 0 ? (
        <div>
          {lorries.map((lorry) => (
            <LorryCard key={lorry.registration_number}>
              <div>
                <strong>{lorry.registration_number}</strong>
                <p>{lorry.model} ({lorry.year_built})</p>
                <p>{lorry.owner_phone}</p>
              </div>
              <DeleteButton onClick={() => handleDeleteLorry(lorry.registration_number)}>
                Delete
              </DeleteButton>
            </LorryCard>
          ))}
        </div>
      ) : (
        <p>No lorries found.</p>
      )}
    </Container>
  );
};

export default HomePage;
